import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: antonFamily } = loadAnton();
const { fontFamily: playfairFamily } = loadPlayfair();



export type MaskRevealAnimationProps = Record<string, any>;

const MaskRevealAnimation: React.FC<MaskRevealAnimationProps> = ({
  backgroundColor = "#3858e9",
  transparentBackground = false,
  durationInSeconds = 5,
  maskColor = "#ffffff",
  baseTextLine1 = "CHANGE",
  baseTextLine2 = "MINDS",
  maskTextLine1 = "Start with",
  maskTextLine2 = "your own",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Safe background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Sizing and motion calculations
  const radius = height * 0.65;
  const startOffset = -radius * 1.5; // Ensure circles start completely off-canvas

  // Animation timeline mapped to absolute frames based on fps
  // Total duration in frames: durationInSeconds * fps
  const totalFrames = durationInSeconds * fps;
  const halfDuration = totalFrames / 2;

  // 1. Entrance Phase: Move together in the first half of the animation
  const leftXEntrance = spring({
    fps,
    frame: frame - 5, // Slight delay before entrance begins
    config: { damping: 14, mass: 1, stiffness: 60 },
    from: startOffset,
    to: width * 0.35, // Move inward closer to center to reveal full text
  });

  const rightXEntrance = spring({
    fps,
    frame: frame - 5,
    config: { damping: 14, mass: 1, stiffness: 60 },
    from: width - startOffset,
    to: width * 0.65, // Move inward closer to center to reveal full text
  });

  // 2. Exit Phase: Move back out in the second half of the animation
  const leftXExit = spring({
    fps,
    frame: frame - halfDuration,
    config: { damping: 14, mass: 1, stiffness: 60 },
    from: width * 0.35,
    to: startOffset,
  });

  const rightXExit = spring({
    fps,
    frame: frame - halfDuration,
    config: { damping: 14, mass: 1, stiffness: 60 },
    from: width * 0.65,
    to: width - startOffset,
  });

  // Choose the position depending on the timeline state
  const leftX = frame < halfDuration ? leftXEntrance : leftXExit;
  const rightX = frame < halfDuration ? rightXEntrance : rightXExit;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* 
        Synchronous SVG Mask Definition 
        Local URL masking prevents network loading flicker and is safe for Remotion.
      */}
      <svg width={0} height={0} style={{ position: "absolute" }}>
        <defs>
          <mask id="dual-circle-mask">
            {/* Black base hides the foreground layer by default */}
            <rect width="100%" height="100%" fill="black" />
            {/* White circles reveal the foreground layer as they move in and out */}
            <circle cx={leftX} cy={height / 2} r={radius} fill="white" />
            <circle cx={rightX} cy={height / 2} r={radius} fill="white" />
          </mask>
        </defs>
      </svg>

      {/* BACKGROUND LAYER: Blue background, White thick text */}
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
        <div
          style={{
            fontFamily: antonFamily,
            color: maskColor,
            fontSize: 350 * s,
            lineHeight: 0.9,
            textAlign: "center",
            display: "flex",
            flexDirection: "column",
            textTransform: "uppercase",
            letterSpacing: "0.02em",
          }}
        >
          <span>{baseTextLine1}</span>
          <span>{baseTextLine2}</span>
        </div>
      </AbsoluteFill>

      {/* FOREGROUND LAYER: White background, Blue serif text. Gated by the circle mask. */}
      <AbsoluteFill
        style={{
          backgroundColor: maskColor,
          mask: "url(#dual-circle-mask)",
          WebkitMask: "url(#dual-circle-mask)",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div
          style={{
            fontFamily: playfairFamily,
            color: backgroundColor,
            fontSize: 170 * s,
            lineHeight: 1.1,
            textAlign: "center",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <span>{maskTextLine1}</span>
          <span>{maskTextLine2}</span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default MaskRevealAnimation;